const historial = $input.all().filter(item => item.json.CallSid);
const mensajeNuevo = $('Webhook1').first().json.body.SpeechResult;

const messages = historial.map(item => ({
  role: item.json.Rol,
  content: item.json.Mensaje
}));

messages.push({
  role: "user",
  content: mensajeNuevo
});

return [{ json: { messages } }];

const callSid = $('Webhook1').first().json.body.CallSid;
const mensajeUsuario = $('Webhook1').first().json.body.SpeechResult;
const respuestaClaude = $('Edit Fields').first().json.respuesta_texto;
const fecha = new Date().toISOString();

return [
  { json: { CallSid: callSid, Rol: "user", Mensaje: mensajeUsuario, Fecha: fecha } },
  { json: { CallSid: callSid, Rol: "assistant", Mensaje: respuestaClaude, Fecha: fecha } }
];

const rawText = $json.content[0].text;
const limpio = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
const parsed = JSON.parse(limpio);

return [{
  json: {
    texto: parsed.texto,
    accion: parsed.accion
  }
}];
